class Solution { vector<int> zero,one,count;int nodes=1;void update(int value,int delta){int node=0;count[node]+=delta;for(int bit=18;bit>=0;--bit){int direction=value>>bit&1;int next=direction?one[node]:zero[node];if(!next&&delta>0){next=nodes++;(direction?one[node]:zero[node])=next;}node=next;count[node]+=delta;}}int best(int value){int node=0,answer=0;for(int bit=18;bit>=0;--bit){int direction=value>>bit&1,opposite=direction?zero[node]:one[node];if(opposite&&count[opposite]){answer|=1<<bit;node=opposite;}else node=direction?one[node]:zero[node];}return answer;}public: vector<int> maxGeneticDifference(vector<int>& parents,vector<vector<int>>& queries){int n=parents.size(),root=0;vector<vector<int>> children(n);vector<vector<pair<int,int>>> attached(n);for(int i=0;i<n;++i)if(parents[i]<0)root=i;else children[parents[i]].push_back(i);for(int i=0;i<(int)queries.size();++i)attached[queries[i][0]].push_back({queries[i][1],i});zero.resize((n+1)*20);one.resize((n+1)*20);count.resize((n+1)*20);vector<int> answer(queries.size());vector<pair<int,bool>> stack={{root,false}};while(!stack.empty()){auto [node,exit]=stack.back();stack.pop_back();if(exit){update(node,-1);continue;}update(node,1);for(auto [value,index]:attached[node])answer[index]=best(value);stack.push_back({node,true});for(auto it=children[node].rbegin();it!=children[node].rend();++it)stack.push_back({*it,false});}return answer;} };
